// Slack signs "v0:<timestamp>:<raw body>" with the app's Signing Secret.
// The raw bytes live in the binary "data" property because the Webhook node has
// Raw Body on; the parsed JSON is still in $json.body.
const item = $input.first();
const headers = item.json.headers || {};
const body = item.json.body || {};
let raw = '';
try {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (e) {
  if (item.binary && item.binary.data && item.binary.data.data) raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
}
const ts = String(headers['x-slack-request-timestamp'] || '');
const sig = String(headers['x-slack-signature'] || '');
const ageSeconds = Math.abs(Math.floor(Date.now() / 1000) - Number(ts));
const event = body.event || {};
const user = event.user || {};
return [{ json: {
  sig_base: 'v0:' + ts + ':' + raw,
  slack_signature: sig,
  timestamp_ok: /^\d+$/.test(ts) && ageSeconds <= 300,
  has_signing_secret: !!$env.SLACK_SIGNING_SECRET,
  body_type: body.type || '',
  challenge: body.challenge || '',
  event_type: event.type || '',
  slack_user_id: user.id || '',
  email: String((user.profile && user.profile.email) || '').trim().toLowerCase(),
  is_bot: !!user.is_bot,
  retry_num: headers['x-slack-retry-num'] || null
} }];

const j = $input.first().json;
const expected = 'v0=' + (j.computed_hmac || '');
const given = j.slack_signature || '';
// Constant-time-ish compare: always walk the full expected length.
let same = expected.length === given.length;
for (let i = 0; i < expected.length; i++) same = (expected.charCodeAt(i) === (given.charCodeAt(i) || -1)) && same;
const verified = j.has_signing_secret && j.timestamp_ok && same;
let status = 200, response = {}, reason = '';
if (!verified) {
  status = 401;
  response = { error: 'signature verification failed' };
  reason = !j.has_signing_secret ? 'SLACK_SIGNING_SECRET is not set on the n8n service' : !j.timestamp_ok ? 'timestamp missing or older than 5 minutes' : 'HMAC mismatch';
} else if (j.body_type === 'url_verification') {
  response = { challenge: j.challenge };
}
const proceed = verified && j.body_type === 'event_callback' && j.event_type === 'team_join' && !j.is_bot && !!j.slack_user_id;
return [{ json: { status, response, verified, reason, proceed, slack_user_id: j.slack_user_id, email: j.email, retry_num: j.retry_num } }];

function resolveChannels(patterns, marketSlug) {
  const out = [];
  for (const p of patterns) {
    const pattern = String(p || '').trim();
    if (!pattern) continue;
    if (pattern.includes('<market>')) {
      if (!marketSlug) continue;
      out.push(pattern.replace('<market>', marketSlug));
    } else {
      out.push(pattern);
    }
  }
  return [...new Set(out)];
}

// Same algorithm as slugify() in slack-onboarding-normalize.js. It is repeated
// here because team_members stores first/last name, not the slug, so B and C
// re-derive it — and the n8n Code node can only embed one file.
function slugify(s) {
  return String(s || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

// Per-rep private channel: sales-<market>-<firstname>-<lastname>.
// Slack caps channel names at 80 characters.
function repChannelName(marketSlug, slug) {
  return `sales-${marketSlug}-${slug}`.slice(0, 80);
}

// ---- workflow glue (the functions above are scripts/lib/slack-onboarding-resolve.js) ----
const member = $('Lookup Member').first().json;
const patterns = $('Lookup Role Channels').all().map((i) => i.json.channel_pattern).filter(Boolean);
const marketRow = $('Lookup Market Slug').first().json || {};
const marketSlug = marketRow.slug || '';
const alerts = [];
if (patterns.length === 0) alerts.push('🟠 NO ROLE MAPPING · slack_role_channels has no rows for role ' + member.role);
if (member.market_code && !marketSlug) alerts.push('🟠 UNKNOWN MARKET · slack_market_slugs has no row for ' + member.market_code);
const channelNames = resolveChannels(patterns, marketSlug);
const slug = slugify(member.first_name) + '-' + slugify(member.last_name);
let repChannel = null;
if (member.role === 'sales_rep') {
  if (marketSlug) repChannel = repChannelName(marketSlug, slug);
  else alerts.push('🟠 NO REP CHANNEL · sales_rep ' + member.email + ' has no market, so the rep channel cannot be named');
}
return [{ json: {
  member_id: member.id,
  email: member.email,
  first_name: member.first_name,
  last_name: member.last_name,
  role: member.role,
  market_code: member.market_code || null,
  market_slug: marketSlug,
  slack_user_id: $('Verify & Route').first().json.slack_user_id,
  channel_names: channelNames,
  rep_channel_name: repChannel,
  lookup_names: repChannel ? channelNames.concat([repChannel]) : channelNames,
  alerts
} }];

const plan = $('Resolve Channels').first().json;
const rows = $('Lookup Slack Channels').all().map((i) => i.json).filter((r) => r.channel_name);
const byName = Object.fromEntries(rows.map((r) => [r.channel_name, r.slack_channel_id]));
const alerts = [...plan.alerts];
const invites = [];
for (const name of plan.channel_names) {
  if (byName[name]) invites.push({ name, id: byName[name] });
  else alerts.push('🟠 MISSING CHANNEL · ' + name + ' · not in slack_channels');
}
const existingRepChannelId = plan.rep_channel_name ? (byName[plan.rep_channel_name] || null) : null;
const live = $env.SLACK_ONBOARDING_MODE === 'live';
const hasDispatch = plan.channel_names.includes('dispatch');
const names = invites.map((i) => '#' + i.name).concat(plan.rep_channel_name ? ['#' + plan.rep_channel_name] : []);
let dm = "You're all set. Your channels: " + names.join(', ') + '.';
if (hasDispatch) dm += ' Urgent = call the Five9 dispatch line. Not urgent = post in #dispatch.';
const label = plan.first_name + ' ' + plan.last_name + ' · ' + plan.role + ' · ' + (plan.market_code || 'company-wide');
const shadow = '[SHADOW] ✅ ONBOARDED · ' + label + ' · ' + invites.length + ' channels'
  + ' · would invite: ' + (invites.map((i) => '#' + i.name).join(', ') || 'none')
  + (plan.rep_channel_name ? ' · would ' + (existingRepChannelId ? 'reuse' : 'create') + ' private #' + plan.rep_channel_name : '')
  + ' · row left as-is (shadow)'
  + (alerts.length ? '\n' + alerts.join('\n') : '');
return [{ json: { ...plan, invites, existing_rep_channel_id: existingRepChannelId, needs_rep_channel: !!plan.rep_channel_name, live, mode: live ? 'live' : 'shadow', dm_text: dm, label, n_channels: invites.length, shadow_text: shadow, alerts } }];

const alerts = [];
let invited = 0;
if ($('Invite to Channel').isExecuted) {
  const wanted = $('Fan Out Invites').all().map((i) => i.json);
  const results = $('Invite to Channel').all().map((i) => i.json);
  results.forEach((r, idx) => {
    const name = (wanted[idx] || {}).name || '?';
    if (r.ok === true || r.error === 'already_in_channel') invited++;
    else alerts.push('🟠 INVITE FAILED · #' + name + ' · ' + (r.error || 'unknown error'));
  });
}
return [{ json: { invited, invite_alerts: alerts } }];

const plan = $('Plan Provisioning').first().json;
const alerts = [];
let id = plan.existing_rep_channel_id || null;
let source = id ? 'slack_channels row' : null;
if (!id && $('Create Rep Channel').isExecuted) {
  const r = $('Create Rep Channel').first().json;
  if (r.ok === true && r.channel && r.channel.id) { id = r.channel.id; source = 'created'; }
  else if (r.error === 'name_taken' && $('List Channels').isExecuted) {
    for (const page of $('List Channels').all()) {
      const hit = ((page.json && page.json.channels) || []).find((ch) => ch.name === plan.rep_channel_name);
      if (hit) { id = hit.id; source = 'found existing'; break; }
    }
    if (!id) alerts.push('🟠 REP CHANNEL · #' + plan.rep_channel_name + ' already exists (name_taken) but Reece Bot cannot see it — add the bot to that channel, then re-run');
  } else {
    alerts.push('🟠 REP CHANNEL FAILED · #' + plan.rep_channel_name + ' · ' + (r.error || 'unknown error'));
  }
}
return [{ json: { rep_channel_id: id, rep_channel_name: plan.rep_channel_name, rep_channel_source: source, rep_alerts: alerts } }];

const plan = $('Plan Provisioning').first().json;
const alerts = [...plan.alerts];
let invited = 0;
if ($('Collect Invite Results').isExecuted) {
  const r = $('Collect Invite Results').first().json;
  invited = r.invited;
  alerts.push(...r.invite_alerts);
}
let rep = '';
if ($('Rep Channel Id').isExecuted) {
  const r = $('Rep Channel Id').first().json;
  alerts.push(...r.rep_alerts);
  if (r.rep_channel_id) rep = ' · rep channel #' + r.rep_channel_name + ' (' + r.rep_channel_source + ')';
}
const dm = $('Welcome DM').first().json;
if (!dm || dm.ok !== true) alerts.push('🟠 DM FAILED · ' + ((dm && dm.error) || 'unknown error'));
const text = '✅ ONBOARDED · ' + plan.label + ' · ' + invited + ' channels' + rep
  + (invited < plan.invites.length ? ' (' + (plan.invites.length - invited) + ' failed)' : '')
  + (alerts.length ? '\n' + alerts.join('\n') : '');
return [{ json: { text } }];

// Slack answers HTTP 200 with ok:false on every API error, so a plain HTTP node
// never turns red. Fail the execution here so a missing token, a wrong channel
// id or a missing scope shows up as a failed run instead of a silent no-op.
const r = $input.first().json;
if (!r || r.ok !== true) {
  const err = r && r.error ? r.error : JSON.stringify(r);
  const hint = err === 'not_authed' || err === 'invalid_auth' ? ' — SLACK_BOT_TOKEN missing or wrong on the n8n service'
    : err === 'channel_not_found' ? ' — SLACK_OPS_ALERTS_CHANNEL_ID wrong, or Reece Bot is not in #ops-alerts'
    : err === 'missing_scope' ? ' — add the scope to the Slack app and reinstall it'
    : '';
  throw new Error('Slack API call failed: ' + err + hint);
}
return [{ json: { ok: true, ts: r.ts || null, channel: r.channel || null } }];
